/**
 * @file Built-in function data from `data/builtins.json`, generated by
 * `scripts/extract-builtins` from the Basic Programming Guide and the CLIPS
 * 6.4.2 source, and which built-in arguments name a class, template, slot,
 * module or logical name.
 */

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { SyntaxNode } from 'tree-sitter';
import type { SymbolTable } from './symbolTable.js';

/** One entry of `data/builtins.json`. */
export interface BuiltinFunction {
  /** CLIPS name, e.g. `"str-cat"`. */
  name: string;
  /** BPG section, e.g. `"12.5.23"`; `null` if not in the BPG. */
  section: string | null;
  /** BPG section title, e.g. `"Modulus"`. */
  title: string | null;
  /** BPG page. */
  page: number | null;
  /** First sentence of the BPG description, or a placeholder. */
  description: string;
  /** Call syntax, e.g. `(mod <numeric-expression> <numeric-expression>)`; may have several lines. */
  syntax: string | null;
  /** Whether `syntax` is from the manual or built from the `AddUDF` registration. */
  syntax_source: 'manual' | 'synthesized-from-source' | null;
  /** Minimum argument count. */
  min_args: string | null;
  /** Maximum argument count, or `"UNBOUNDED"`. */
  max_args: string | null;
  /** Return types, e.g. `["integer", "float"]`. */
  return_types: string[] | null;
  /** C file that registers the function, e.g. `"emathfun.c"`. */
  source_file: string | null;
  /** Type of each required argument, e.g. `["numeric", "numeric"]`. */
  arg_types: string[] | null;
  /** Type of the repeating last argument; `null` if not variadic. */
  variadic_type: string | null;
}

/** Layout of `data/builtins.json`. */
interface BuiltinsData {
  /** Provenance: CLIPS version and the release zip's hashes. */
  meta: {
    clips_version: string;
    source_archive: { filename: string; sha256: string; sha1: string; md5: string };
  };
  /** Entries by function name. */
  functions: Record<string, BuiltinFunction>;
}

/**
 * Reads `data/builtins.json`; empty if it is missing.
 *
 * @returns The functions and the CLIPS version.
 */
function loadBuiltins(): { functions: ReadonlyMap<string, BuiltinFunction>; clipsVersion: string | null } {
  // Read relative to this file rather than imported, so it works from src/ and dist/.
  const dataPath = join(dirname(fileURLToPath(import.meta.url)), '..', 'data', 'builtins.json');
  let data: BuiltinsData;
  try {
    data = JSON.parse(readFileSync(dataPath, 'utf8'));
  } catch {
    return { functions: new Map(), clipsVersion: null };
  }
  return { functions: new Map(Object.entries(data.functions)), clipsVersion: data.meta?.clips_version ?? null };
}

/** The built-in data, read once at startup. */
const loaded = loadBuiltins();

/** All built-in functions by name. */
export const BUILTIN_FUNCTIONS: ReadonlyMap<string, BuiltinFunction> = loaded.functions;

/** CLIPS version the data was extracted from; `null` if the file is missing. */
export const CLIPS_VERSION: string | null = loaded.clipsVersion;

/** What a built-in expects at an argument position. */
export type ArgumentRole = 'class' | 'template' | 'slot' | 'module' | 'logicalName' | null;

/** Built-ins whose syntax doesn't name these arguments usefully. */
const ARGUMENT_ROLE_OVERRIDES: Record<string, ArgumentRole[]> = {
  'deftemplate-slot-facet-existp': ['template', 'slot', null],
  'deftemplate-slot-facet-value': ['template', 'slot', null],
  // open defines a new logical name.
  open: [null, null, null]
};

/** Argument roles; with `repeatLast`, further arguments take the last role. */
interface ArgumentRoles {
  /** Role of each argument by position. */
  roles: ArgumentRole[];
  /** Further arguments take the last role, e.g. <module-name>+. */
  repeatLast: boolean;
}

/** {@link builtinArgumentRoles} results by function name. */
const argumentRoleCache = new Map<string, ArgumentRoles | null>();

/**
 * Argument roles from the placeholder names in a built-in's syntax, e.g.
 * `(slot-range <class-name> <slot-name>)`.
 *
 * @param name - The built-in.
 * @returns The roles, or `null` if none apply.
 */
function builtinArgumentRoles(name: string): ArgumentRoles | null {
  if (argumentRoleCache.has(name)) return argumentRoleCache.get(name)!;
  const override = ARGUMENT_ROLE_OVERRIDES[name];
  let result: ArgumentRoles | null = override ? { roles: override, repeatLast: false } : null;
  const signature = BUILTIN_FUNCTIONS.get(name)?.syntax?.split('\n')[0] ?? '';
  if (!result && signature.startsWith(`(${name} `)) {
    const placeholders = [...signature.matchAll(/<([^>]+)>([*+]?)/g)];
    const roles = placeholders.map(([, p]): ArgumentRole => {
      if (/^class\d?(-name|-expression)?$/.test(p)) return 'class';
      if (p === 'deftemplate-name') return 'template';
      if (/^slot(-name)?(-expression)?$/.test(p)) return 'slot';
      if (p === 'module-name') return 'module';
      if (p === 'logical-name') return 'logicalName';
      return null;
    });
    result = { roles, repeatLast: placeholders.length > 0 && placeholders[placeholders.length - 1][2] !== '' };
  }
  if (result && !result.roles.some((r) => r !== null)) result = null;
  argumentRoleCache.set(name, result);
  return result;
}

/** A literal argument of a built-in. */
export interface BuiltinArgument {
  /** What the argument names. */
  role: ArgumentRole;
  /** The called built-in. */
  functionName: string;
  /** For a slot: the literal class in the same call. */
  classLiteral: string | null;
  /** For a slot: the literal template in the same call. */
  templateLiteral: string | null;
}

/**
 * The role of a constant passed to a built-in such as `slot-range`.
 *
 * @param constant - A call argument.
 * @param table - The lookup scope; a user function of the same name shadows the built-in.
 * @returns The role, or `null`.
 */
export function builtinArgumentAt(constant: SyntaxNode, table: SymbolTable): BuiltinArgument | null {
  const call = constant.parent;
  const head = call?.type === 'function_call' ? call.namedChildren[0] : null;
  if (!call || head?.type !== 'function_name' || table.functionLike.has(head.text)) return null;
  const spec = builtinArgumentRoles(head.text);
  if (!spec) return null;

  const args = call.namedChildren.slice(1);
  const index = args.findIndex((a) => a.id === constant.id);
  if (index < 0) return null;
  const role = index < spec.roles.length ? spec.roles[index] : spec.repeatLast ? spec.roles[spec.roles.length - 1] : null;
  /** The symbol given for role `r` in this call, unless it is `constant` itself. */
  const literal = (r: ArgumentRole): string | null => {
    const arg = args[spec.roles.indexOf(r)];
    return arg && arg.id !== constant.id && arg.type === 'constant' && arg.firstChild?.type === 'symbol' ? arg.text : null;
  };
  return { role, functionName: head.text, classLiteral: literal('class'), templateLiteral: literal('template') };
}
